#!/usr/bin/env node
/**
 * Generate PWA icon set from public/branding/logo-original.png.
 * Outputs to public/icons/: icon-192.png, icon-512.png,
 * icon-maskable-512.png, apple-touch-icon.png, favicon.ico (32 px PNG).
 *
 * Usage: pnpm icons:generate
 */
import sharp from 'sharp';
import { mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SRC = resolve(__dirname, '../public/branding/logo-original.png');
const OUT = resolve(__dirname, '../public/icons');
mkdirSync(OUT, { recursive: true });

const BG = { r: 247, g: 244, b: 237, alpha: 1 };
const MASKABLE_PAD = 0.2;

async function generate() {
  // Standard icons — content fitted with cream background
  for (const px of [192, 512]) {
    await sharp(SRC)
      .resize(px, px, { fit: 'contain', background: BG })
      .png()
      .toFile(resolve(OUT, `icon-${px}.png`));
    console.log(`icon-${px}.png`);
  }

  // Maskable 512 — content at 60% centre, safe-zone padding
  const contentSize = Math.round(512 * (1 - MASKABLE_PAD * 2));
  const inner = await sharp(SRC)
    .resize(contentSize, contentSize, { fit: 'contain', background: { r: 247, g: 244, b: 237, alpha: 0 } })
    .toBuffer();
  await sharp({ create: { width: 512, height: 512, channels: 4, background: { r: 247, g: 244, b: 237, alpha: 255 } } })
    .composite([{ input: inner, gravity: 'center' }])
    .png()
    .toFile(resolve(OUT, 'icon-maskable-512.png'));
  console.log('icon-maskable-512.png');

  // Apple touch icon 180 px
  await sharp(SRC)
    .resize(180, 180, { fit: 'contain', background: BG })
    .png()
    .toFile(resolve(OUT, 'apple-touch-icon.png'));
  console.log('apple-touch-icon.png');

  // Favicon — 32 px PNG (browsers accept PNG favicon via <link rel="icon">)
  await sharp(SRC)
    .resize(32, 32, { fit: 'contain', background: BG })
    .png()
    .toFile(resolve(OUT, 'favicon.ico'));
  console.log('favicon.ico');

  console.log(`\nAll icons written to ${OUT}`);
}

generate().catch((err) => {
  console.error(err);
  process.exit(1);
});

const KEY = 'btw:lastVisit';

export const useLastVisit = (): {
  getLastVisit: () => number;
  recordVisit: () => void;
  isNew: (createdAt: number) => boolean;
} => {
  const getLastVisit = (): number => {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(KEY) : null;
    return raw ? parseInt(raw, 10) : 0;
  };

  const recordVisit = (): void => {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(KEY, String(Date.now()));
    }
  };

  const isNew = (createdAt: number): boolean => createdAt > getLastVisit();

  return { getLastVisit, recordVisit, isNew };
};

import { ref, type Ref } from 'vue';

export interface ToastAction {
  label: string;
  fn: () => void;
}

export interface Toast {
  id: string;
  message: string;
  action?: ToastAction;
}

const TOAST_TTL_MS = 4000;

// Module-level state — singleton across the app.
const toasts = ref<Toast[]>([]);
const timers = new Map<string, ReturnType<typeof setTimeout>>();

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `toast-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
};

const dismiss = (id: string): void => {
  const timer = timers.get(id);
  if (timer) {
    clearTimeout(timer);
    timers.delete(id);
  }
  toasts.value = toasts.value.filter((t) => t.id !== id);
};

const addToast = (message: string, action?: ToastAction): void => {
  const id = generateId();
  const toast: Toast = action ? { id, message, action } : { id, message };
  toasts.value = [...toasts.value, toast];
  if (typeof window !== 'undefined') {
    const handle = setTimeout(() => dismiss(id), TOAST_TTL_MS);
    timers.set(id, handle);
  }
};

export const useToasts = (): {
  toasts: Readonly<Ref<readonly Toast[]>>;
  addToast: (message: string, action?: ToastAction) => void;
  dismiss: (id: string) => void;
} => ({
  toasts: toasts as Readonly<Ref<readonly Toast[]>>,
  addToast,
  dismiss,
});

import { registerSW } from 'virtual:pwa-register';
import { useToasts } from '@/composables/useToasts';

export function initPWA(): void {
  const { addToast } = useToasts();
  let updateSW: ((reloadPage?: boolean) => Promise<void>) | undefined;

  updateSW = registerSW({
    onNeedRefresh() {
      addToast('Update available', {
        label: 'Refresh',
        fn: () => updateSW?.(true),
      });
    },
    onOfflineReady() {
      addToast('Ready to work offline');
    },
  });
}

import { GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged, type User } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import type { UserProfile } from '@/domain/types';

const provider = new GoogleAuthProvider();

async function upsertUserProfile(uid: string, email: string, displayName: string): Promise<void> {
  const ref = doc(db, 'users', uid);
  await setDoc(ref, { uid, email, displayName, lastLoginAt: Date.now() } satisfies UserProfile, {
    merge: true,
  });
}

export function initAuthListener(callback: (user: UserProfile | null) => void): () => void {
  return onAuthStateChanged(auth, (firebaseUser: User | null) => {
    if (firebaseUser) {
      const { uid, email, displayName } = firebaseUser;
      const normalizedEmail = (email ?? '').trim().toLowerCase();

      // Asynchronously upsert profile to update lastLoginAt and ensure document exists
      upsertUserProfile(uid, normalizedEmail, displayName ?? '').catch(console.error);

      callback({
        uid,
        email: normalizedEmail,
        displayName: displayName ?? '',
        lastLoginAt: Date.now(),
      });
    } else {
      callback(null);
    }
  });
}

export async function signInWithGoogle(): Promise<UserProfile> {
  const result = await signInWithPopup(auth, provider);
  const { uid, email, displayName } = result.user;
  const normalizedEmail = (email ?? '').trim().toLowerCase();
  await upsertUserProfile(uid, normalizedEmail, displayName ?? '');
  return {
    uid,
    email: normalizedEmail,
    displayName: displayName ?? '',
    lastLoginAt: Date.now(),
  };
}

export async function signOutUser(): Promise<void> {
  await signOut(auth);
}

import { collection, doc, increment, onSnapshot, query, setDoc, where } from 'firebase/firestore';
import { db } from './firebase';
import type { CatalogEntry } from '@/domain/types';

export async function recordCatalogUse(
  ownerUid: string,
  name: string,
  category: string,
): Promise<void> {
  const nameLower = name.toLowerCase();
  const ref = doc(db, 'catalog', `${ownerUid}_${nameLower}_${category}`);
  await setDoc(ref, { ownerUid, name, category, usageCount: increment(1) }, { merge: true });
}

export function subscribeCatalog(
  uid: string,
  callback: (entries: CatalogEntry[]) => void,
): () => void {
  const q = query(collection(db, 'catalog'), where('ownerUid', '==', uid));
  return onSnapshot(q, (snap) => {
    callback(snap.docs.map((d) => d.data() as CatalogEntry));
  });
}

import { initializeApp, getApps } from 'firebase/app';
import { getAuth, connectAuthEmulator } from 'firebase/auth';
import {
  getFirestore,
  connectFirestoreEmulator,
  enableIndexedDbPersistence,
} from 'firebase/firestore';

const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID,
};

const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0]!;

export const auth = getAuth(app);
export const db = getFirestore(app);

// Enable offline persistence — errors (e.g. multiple tabs, private browsing) are non-blocking.
try {
  await enableIndexedDbPersistence(db);
} catch (err) {
  console.warn('[firebase] IndexedDB persistence unavailable:', err);
}

// Connect to local emulators in dev mode (only once per process; try/catch guards HMR re-imports).
if (import.meta.env.DEV) {
  try {
    connectAuthEmulator(auth, 'http://localhost:9099', { disableWarnings: true });
    connectFirestoreEmulator(db, 'localhost', 8080);
  } catch {
    // Already connected — safe to ignore on hot-module reload.
  }
}

import {
  collection,
  deleteDoc,
  doc,
  onSnapshot,
  orderBy,
  query,
  setDoc,
  updateDoc,
} from 'firebase/firestore';
import { db } from './firebase';
import { recordCatalogUse } from './catalog.service';
import type { Item } from '@/domain/types';
import type { ULID } from '@/domain/id';

function itemDoc(listId: ULID, itemId: ULID) {
  return doc(db, 'lists', listId, 'items', itemId);
}

export async function addItem(listId: ULID, item: Item): Promise<void> {
  await setDoc(itemDoc(listId, item.id), { ...item });
  // fire-and-forget: catalog errors must not block item creation
  recordCatalogUse(item.createdByUid, item.name, item.category).catch(console.error);
}

export async function toggleChecked(
  listId: ULID,
  itemId: ULID,
  currentChecked: boolean,
): Promise<void> {
  await updateDoc(itemDoc(listId, itemId), { checked: !currentChecked, updatedAt: Date.now() });
}

export async function updateItem(
  listId: ULID,
  itemId: ULID,
  patch: Partial<Pick<Item, 'name' | 'quantity' | 'category' | 'note' | 'checked'>>,
): Promise<void> {
  await updateDoc(itemDoc(listId, itemId), { ...patch, updatedAt: Date.now() });
}

export async function removeItem(listId: ULID, itemId: ULID): Promise<void> {
  await deleteDoc(itemDoc(listId, itemId));
}

export function subscribeItems(listId: ULID, callback: (items: Item[]) => void): () => void {
  const q = query(collection(db, 'lists', listId, 'items'), orderBy('createdAt', 'asc'));
  return onSnapshot(q, (snap) => {
    callback(snap.docs.map((d) => d.data() as Item));
  });
}

import {
  arrayRemove,
  arrayUnion,
  collection,
  doc,
  onSnapshot,
  orderBy,
  query,
  setDoc,
  updateDoc,
  where,
} from 'firebase/firestore';
import { db } from './firebase';
import { findUserByEmail } from './users.service';
import type { List } from '@/domain/types';
import type { ULID } from '@/domain/id';

export class UserNotRegisteredError extends Error {
  constructor(email: string) {
    super(`No user registered with email: ${email}`);
    this.name = 'UserNotRegisteredError';
  }
}

export async function createList(list: List): Promise<void> {
  const ref = doc(db, 'lists', list.id);
  await setDoc(ref, { ...list, collaboratorUids: [...list.collaboratorUids] });
}

export async function renameList(id: ULID, name: string): Promise<void> {
  await updateDoc(doc(db, 'lists', id), { name, updatedAt: Date.now() });
}

export async function softDeleteList(id: ULID): Promise<void> {
  const now = Date.now();
  await updateDoc(doc(db, 'lists', id), { deletedAt: now, updatedAt: now });
}

export async function restoreList(id: ULID): Promise<void> {
  await updateDoc(doc(db, 'lists', id), { deletedAt: null, updatedAt: Date.now() });
}

export async function addCollaboratorByUid(listId: ULID, uid: string): Promise<void> {
  await updateDoc(doc(db, 'lists', listId), {
    collaboratorUids: arrayUnion(uid),
    updatedAt: Date.now(),
  });
}

export async function addCollaborator(listId: ULID, email: string): Promise<void> {
  const profile = await findUserByEmail(email);
  if (!profile) throw new UserNotRegisteredError(email);
  await updateDoc(doc(db, 'lists', listId), {
    collaboratorUids: arrayUnion(profile.uid),
    updatedAt: Date.now(),
  });
}

export async function removeCollaborator(listId: ULID, uid: string): Promise<void> {
  await updateDoc(doc(db, 'lists', listId), {
    collaboratorUids: arrayRemove(uid),
    updatedAt: Date.now(),
  });
}

export async function leaveList(listId: ULID, selfUid: string): Promise<void> {
  return removeCollaborator(listId, selfUid);
}

export function subscribeUserLists(uid: string, callback: (lists: List[]) => void): () => void {
  const q = query(
    collection(db, 'lists'),
    where('ownerUid', '==', uid),
    orderBy('updatedAt', 'desc'),
  );
  return onSnapshot(q, (snap) => {
    callback(snap.docs.map((d) => d.data() as List));
  });
}

import { collection, getDocs, query, where } from 'firebase/firestore';
import { db } from './firebase';
import type { UserProfile } from '@/domain/types';

export async function findUserByEmail(email: string): Promise<UserProfile | null> {
  const normalized = email.trim().toLowerCase();
  const q = query(collection(db, 'users'), where('email', '==', normalized));
  const snap = await getDocs(q);
  if (snap.empty) return null;
  return snap.docs[0]!.data() as UserProfile;
}
